def find_connected_components(grid):
    h, w = len(grid), len(grid[0])
    visited = set()
    components = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2 and (r, c) not in visited:
                # BFS to find connected 2x2 blocks
